function calPoints(operations) {
  const record = [];
  for (let i = 0; i < operations.length; i++) {
    const op = operations[i];
    if (op === 'C') {
      if (record.length > 0) {
        record.splice(record.length - 1, 1);
      }
    } else if (op === 'D') {
      const prev = record.length > 0 ? record[record.length - 1] : 0;
      record.push(prev * 2);
    } else if (op === '+') {
      const a = record.length > 0 ? record[record.length - 1] : 0;
      const b = record.length > 1 ? record[record.length - 2] : 0;
      record.push(a + b);
    } else {
      record.push(Number(op));
    }
  }
  let total = 0;
  for (let i = 0; i < record.length; i++) {
    total += record[i];
  }
  return total;
}

function calPoints(operations) {
  const stack = [];
  for (let i = 0; i < operations.length; i++) {
    const op = operations[i];
    switch (op) {
      case 'C':
        if (stack.length > 0) {
          stack.pop();
        }
        break;
      case 'D': {
        const prev = stack.length > 0 ? stack[stack.length - 1] : 0;
        stack.push(prev * 2);
        break;
      }
      case '+': {
        const a = stack.length > 0 ? stack[stack.length - 1] : 0;
        const b = stack.length > 1 ? stack[stack.length - 2] : 0;
        stack.push(a + b);
        break;
      }
      default:
        stack.push(Number(op));
        break;
    }
  }
  return stack.reduce((total, value) => total + value, 0);
}

def calPoints(operations: list[str]) -> int:
    record = []
    for op in operations:
        if op == 'C':
            if len(record) > 0:
                record.pop()
        elif op == 'D':
            prev = record[-1] if len(record) > 0 else 0
            record.append(None if prev is None else prev * 2)
        elif op == '+':
            a = record[-1] if len(record) > 0 else 0
            b = record[-2] if len(record) > 1 else 0
            record.append(None if (a is None or b is None) else a + b)
        else:
            try:
                record.append(int(op))
            except ValueError:
                record.append(None)
    if any(x is None for x in record):
        return None
    total = 0
    for val in record:
        total += val
    return total

def calPoints(operations: list[str]) -> int:
